package com.geoattend.app;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.content.pm.ServiceInfo;
import android.location.*;
import android.os.*;
import org.json.JSONObject;
import java.util.concurrent.*;
public final class AttendanceService extends Service implements LocationListener {
 public static volatile boolean running=false;
 public static final String CHANGED="com.geoattend.app.TRACKING_CHANGED",PAUSE="com.geoattend.app.PAUSE";private static final int ID=41;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private LocationManager manager;private Location latest;private SessionStore store;private boolean sending=false,stopping=false;private long lastSent=0;private PowerManager.WakeLock lock;
 private final Runnable tick=new Runnable(){public void run(){if(stopping)return;if(lock!=null)try{lock.acquire(60000);}catch(Exception ignored){}new OfflineAttendance(AttendanceService.this).expire();sendLocation();handler.postDelayed(this,15000);}};
 @Override public void onCreate(){super.onCreate();running=true;store=new SessionStore(this);NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("attendance","Live attendance tracking",NotificationManager.IMPORTANCE_LOW));manager=(LocationManager)getSystemService(LOCATION_SERVICE);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&PAUSE.equals(intent.getAction())){new OfflineAttendance(this).finish();store.prefs().edit().putBoolean("trackingWanted",false).apply();stopping=true;state("Tracking paused",0,0);io.execute(()->{try{new OfflineAttendance(this).sync();Api.call(this,"pause",new JSONObject());}catch(Exception ignored){} });stopSelf();return START_NOT_STICKY;}if(store.token().isEmpty()){stopSelf();return START_NOT_STICKY;}
  try{if(Build.VERSION.SDK_INT>=29)startForeground(ID,notification("Finding your location"),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(ID,notification("Finding your location"));if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){state("Precise location permission needed",0,0);store.prefs().edit().putBoolean("trackingWanted",false).apply();stopSelf();return START_NOT_STICKY;}store.prefs().edit().putBoolean("trackingWanted",true).putBoolean("serviceRunning",true).apply();if(lock==null){lock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"GeoAttend:Attendance");lock.setReferenceCounted(false);lock.acquire(60000);}manager.removeUpdates(this);boolean provider=false;for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){try{manager.requestLocationUpdates(p,10000,0,this,Looper.getMainLooper());if(manager.isProviderEnabled(p))provider=true;}catch(IllegalArgumentException ignored){}}state(provider?"Finding your location":"Turn on device location",0,0);handler.removeCallbacks(tick);handler.post(tick);}catch(Exception e){state("Cannot start tracking. Open the app and check permissions.",0,0);store.prefs().edit().putBoolean("trackingWanted",false).apply();stopSelf();}return START_NOT_STICKY;
 }
 @Override public void onLocationChanged(Location location){if(stopping)return;boolean mocked=Build.VERSION.SDK_INT>=31?location.isMock():location.isFromMockProvider();if(mocked){latest=null;state("Mock location rejected",0,0);return;}if(!location.hasAccuracy()||location.getAccuracy()<=0)return;if(latest==null||SystemClock.elapsedRealtimeNanos()-latest.getElapsedRealtimeNanos()>20000000000L||location.getAccuracy()<=latest.getAccuracy()*1.5f)latest=location;sendLocation();}
 private void sendLocation(){if(stopping||sending||latest==null||SystemClock.elapsedRealtime()-lastSent<10000)return;long age=(SystemClock.elapsedRealtimeNanos()-latest.getElapsedRealtimeNanos())/1000000;if(age<0||age>30000){state("Waiting for fresh GPS",0,0);return;}final Location l=new Location(latest);final String session=store.token();if(session.isEmpty()){stopSelf();return;}sending=true;lastSent=SystemClock.elapsedRealtime();io.execute(()->{try{JSONObject status=Api.call(this,"status",null);if(status.isNull("user"))throw new Api.Failure(401,"Please log in again.");store.savePrivate("cachedStatus",status.toString());OfflineAttendance offline=new OfflineAttendance(this);offline.connected();offline.sync();JSONObject r=Api.call(this,"heartbeat",Api.body("lat",l.getLatitude(),"lon",l.getLongitude(),"accuracy",l.getAccuracy(),"age",age));if(!stopping&&session.equals(store.token()))handler.post(()->{if(!stopping)state(r.optString("state","Connected"),r.optInt("distance"),r.optInt("accuracy"));});}catch(Exception e){handler.post(()->{if(stopping)return;if(e instanceof Api.Failure&&((Api.Failure)e).code==401){store.clear();state("Session expired. Please log in again.",0,0);stopSelf();}else if(e instanceof Api.Failure&&((Api.Failure)e).code<500)state("Offline sync needs attention: "+e.getMessage(),0,0);else{try{String local=new OfflineAttendance(AttendanceService.this).capture(l.getLatitude(),l.getLongitude(),l.getAccuracy(),l.getElapsedRealtimeNanos()/1000000);state(local,store.prefs().getInt("distance",0),store.prefs().getInt("accuracy",0));}catch(Exception problem){state("Cannot save offline attendance: "+problem.getMessage(),0,0);}}});}finally{handler.post(()->sending=false);}});}
 private Notification notification(String text){Intent open=new Intent(this,MainActivity.class);PendingIntent activity=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent pause=PendingIntent.getService(this,1,new Intent(this,AttendanceService.class).setAction(PAUSE),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"attendance").setSmallIcon(R.drawable.ic_location).setContentTitle("Geo Attend · live attendance").setContentText(text).setContentIntent(activity).setOngoing(true).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_SERVICE).addAction(new Notification.Action.Builder(null,"Pause tracking",pause).build()).build();}
 private void state(String text,int distance,int accuracy){store.prefs().edit().putString("trackingStatus",text).putLong("statusAt",System.currentTimeMillis()).putInt("distance",distance).putInt("accuracy",accuracy).apply();if(!stopping)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notification(text));sendBroadcast(new Intent(CHANGED).setPackage(getPackageName()));}
 @Override public void onProviderDisabled(String p){latest=null;state("GPS disabled — turn on device location",0,0);}
 @Override public void onProviderEnabled(String p){state("Finding your location",0,0);}
 @Override public void onStatusChanged(String p,int status,Bundle extras){}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){stopping=true;running=false;handler.removeCallbacksAndMessages(null);try{if(manager!=null)manager.removeUpdates(this);}catch(Exception ignored){}if(lock!=null&&lock.isHeld())lock.release();if(store!=null){store.prefs().edit().putBoolean("serviceRunning",false).apply();sendBroadcast(new Intent(CHANGED).setPackage(getPackageName()));}io.shutdown();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
